1	-- 026 · Stripe and Supabase monitors. Additive rollout: old dashboard signatures and
2	-- probe_load_monitors stay unchanged; old probes never receive an unfamiliar type.
3	begin;
4	
5	alter table public.monitors add column if not exists service_runtime jsonb not null default '{}'::jsonb;
6	
7	-- New entry point, so deployed callers retain exactly their old contract. Counts and
8	-- per-host quotas use the same workspace lock as create_monitor. No quota defaults.
9	create or replace function public.save_service_monitor(
10	  p_workspace_id text, p_id text, p_app_id text, p_type text, p_name text, p_target text,
11	  p_config jsonb, p_sealed text, p_edit boolean, p_max_monitors integer, p_max_type integer,
12	  p_per_host integer, p_interval_sec integer
13	) returns text language plpgsql security invoker set search_path = '' as $fn$
14	declare
15	  old public.monitors;
16	  host text;
17	begin
18	  if p_max_monitors is null or p_max_type is null or p_per_host is null or p_interval_sec is null
19	    or p_max_monitors < 1 or p_max_type < 1 or p_per_host < 1 then
20	    raise exception 'limits_required' using errcode = '22004';
21	  end if;
22	  perform 1 from public.workspaces where id = p_workspace_id for update;
23	  if not found then raise exception 'not_found' using errcode = 'PT404'; end if;
24	  if p_type is null or p_type not in ('stripe', 'supabase') or p_edit is null then
25	    raise exception 'type_not_available';
26	  end if;
27	  perform 1 from public.apps where id = p_app_id and workspace_id = p_workspace_id;
28	  if not found then raise exception 'not_found' using errcode = 'PT404'; end if;
29	  if p_edit then
30	    select * into old from public.monitors where id = p_id and workspace_id = p_workspace_id for update;
